sys_variable_value.value:
(function execute(inputs, outputs) {
    //var current = new GlideRecord("x_asscs_allos_o2c_task");
    //if (current.get("a96131883b0256104a3b3537f4e45a4f")) { //a96131883b0256104a3b3537f4e45a4f , 5653a1e53b1f92104a3b3537f4e45add
    var current = inputs.sysIdTask;
    var myObj = JSON.parse(new SAPintegraUtils().payloadContratoFaturamento(current));

    if (myObj.code == "400") {
        gs.info(myObj.message);
        outputs.error = myObj.code;
        outputs.message = myObj.message;
    } else {
        outputs.payload = myObj.payload;
         gs.info(myObj.message);
    }



})(inputs, outputs);

